puckvzadj	;Set puckvz for a top shelf shot from the distance to the goal line ($11E) over puckvy, at most $7FFF.
	;Gravity word_FFD284 (word_FFD286 with PalMode). Called from doshot
	movem.l	d0-d7/a0-a6,-(sp)
	move.w	(pucky).w,d0
	bpl.w	.0
	neg.w	d0
.0
	subi.w	#$11E,d0
	bpl.w	.1
	neg.w	d0
.1
	swap	d0
	andi.l	#$FFFF0000,d0
	move.w	(puckvy).w,d1
	beq.w	.7
	bpl.w	.2
	neg.w	d1
.2
	move.w	(word_FFD284).w,d2
	tst.w	(PalMode).w
	beq.w	.3
	move.w	(word_FFD286).w,d2
.3
	divu.w	d1,d0
	andi.l	#$FFFF,d0
	divu.w	d2,d0
	tst.w	d0
	bne.w	.4
	move.w	#1,d0
.4
	move.l	#$A0000,d1
	move.w	d0,d3
	mulu.w	d2,d0
	divu.w	d0,d1
	move.w	d2,d4
	add.w	d2,d2
	add.w	d4,d2
	mulu.w	d3,d2
	cmp.l	#$7FFF,d2
	blt.w	.5
	move.w	#$7FFF,d2
.5
	add.w	d2,d1
	tst.w	d1
	bpl.w	.6
	move.w	#$7FFF,d1
.6
	move.w	d1,(puckvz).w
.7
	movem.l	(sp)+,d0-d7/a0-a6
	rts

OneTimerPass	;One-timer pass: puckvz = sqrt(12 * onetimerheight), then puckvx / puckvy toward the target onetimertargetx /
	;onetimertargety in puckvz / 3 frames
	movem.l	d0-d7/a0-a6,-(sp)
	move.w	#$C,d0
	move.w	(onetimerheight).w,d1
	mulu.w	d1,d0
	swap	d0
	andi.l	#$FFFF0000,d0
	jsr	(sroot).l
	move.w	d0,(puckvz).w
	ext.l	d0
	move.w	#3,d4
	divu.w	d4,d0
	clr.l	d1
	move.w	(onetimertargetx).w,d1
	sub.w	(puckx).w,d1
	swap	d1
	tst.w	d0
	bne.w	.0
	move.w	#1,d0
.0
	divs.w	d0,d1
	move.w	d1,(puckvx).w
	clr.l	d1
	move.w	(onetimertargety).w,d1
	sub.w	(pucky).w,d1
	swap	d1
	divs.w	d0,d1
	move.w	d1,(puckvy).w
	movea.l	#puckx,a3
	move.w	(puckvz).w,d0
	jsr	(puckflip).l
	movem.l	(sp)+,d0-d7/a0-a6
	rts

OneTimerTarget	;One-timer pass target for receiver a3: an offset by facing from OneTimerNearTbl / OneTimerFarTbl (skater,
	;near or far from the goal) or OneTimerGoalieTbl, plus a random 0-9 on each axis
	movem.l	d0-d7/a0-a6,-(sp)
	bclr	#2,(sflags6).w
	tst.w	$34(a3)
	bne.w	.0
	movea.l	#OneTimerGoalieTbl,a0
	bra.w	.2
.0
	move.w	Ypos(a3),d0
	btst	#7,pflags(a3)
	bne.w	.1
	neg.w	d0
.1
	bset	#2,(sflags6).w
	movea.l	#OneTimerNearTbl,a0
	cmp.w	#$76,d0
	blt.w	.2
	movea.l	#OneTimerFarTbl,a0
	bclr	#2,(sflags6).w
.2
	move.w	$54(a3),d0
	btst	#7,pflags(a3)
	bne.w	.3
	addq.w	#4,d0
	andi.w	#7,d0
.3
	asl.w	#2,d0
	move.w	(a0,d0.w),d1
	move.w	2(a0,d0.w),d2
	cmpa.l	#OneTimerFarTbl,a0
	bne.w	.6
	move.w	Ypos(a3),d0
	bpl.w	.4
	neg.w	d0
.4
	cmp.w	#$A8,d0
	blt.w	.6
	move.w	(a3),d0
	bpl.w	.5
	neg.w	d0
.5
	cmp.w	#$37,d0
	bgt.w	.6
	move.w	#$119,d2
.6
	btst	#7,pflags(a3)
	bne.w	.7
	neg.w	d1
	neg.w	d2
.7
	move.w	#$A,d0
	jsr	(randomd0).l
	add.w	d0,d1
	move.w	#$A,d0
	jsr	(randomd0).l
	add.w	d0,d2
	move.w	d1,(onetimertargetx).w
	tst.w	$34(a3)
	beq.w	.9
	sub.w	(a3),d1
	bmi.w	.8
	subi.w	#$3C,d1
	bpl.w	.9
	neg.w	d1
	add.w	d1,(onetimertargetx).w
	bra.w	.9
.8
	addi.w	#$3C,d1
	bmi.w	.9
	sub.w	d1,(onetimertargetx).w
.9
	move.w	d2,(onetimertargety).w
	movem.l	(sp)+,d0-d7/a0-a6
	rts

